60	    auto inputShapeX = EnsureNotScalar(inputX->GetStorageShape());
61	    auto inputY = context->GetInputShape(1);
62	    OP_CHECK_NULL_WITH_CONTEXT(context, inputY);
63	    auto inputShapeY = EnsureNotScalar(inputY->GetStorageShape());
64	    auto outZ = context->GetOutputShape(0);
65	    OP_CHECK_NULL_WITH_CONTEXT(context, outZ);
66	    auto outShapeZ = EnsureNotScalar(outZ->GetStorageShape());
67	
68	    // shape校验
69	    OP_CHECK_IF(inputShapeX.GetDimNum() != DIMS_LIMIT || inputShapeY.GetDimNum() != DIMS_LIMIT ||
70	                    outShapeZ.GetDimNum() != DIMS_LIMIT,
