72	                        inputShapeX.GetDimNum(), inputShapeY.GetDimNum(), outShapeZ.GetDimNum()),
73	                return ge::GRAPH_FAILED);
74	
75	    // 获取shape dim值
76	    auto nDim = inputShapeX.GetDim(INDEXZERO);
77	    auto cDim = inputShapeX.GetDim(INDEXONE);
78	    auto hDim = inputShapeX.GetDim(INDEXTWO);
79	    auto wDim = inputShapeX.GetDim(INDEXTHREE);
