81	    // dtype校验
82	    const std::set<ge::DataType> supportedDtype = {ge::DT_FLOAT, ge::DT_INT32};
83	    auto inputDesc = context->GetInputDesc(0);
84	    OP_CHECK_NULL_WITH_CONTEXT(context, inputDesc);
